(()=>{const button=document.querySelector('#expand-policy'),sections=[...document.querySelectorAll('.policy-accordion details')];const sync=()=>button.textContent=sections.every(s=>s.open)?'Collapse all sections':'Expand all sections';button.onclick=()=>{const open=!sections.every(s=>s.open);sections.forEach(s=>s.open=open);sync()};sections.forEach(s=>s.addEventListener('toggle',sync));})();
